import { discountedSubtotal, UnknownDiscountCodeError } from "./src/pricing/domain/discount.ts";

console.log("Testing PRC-DISC-001 requirements:");
console.log("===================================\n");

// Test 1: SAVE10 takes 10% off
console.log("1. SAVE10 takes 10% off:");
const subtotal1 = 10000;
const result1 = discountedSubtotal(subtotal1, "SAVE10");
console.log(`   Input: ${subtotal1} cents (${(subtotal1/100).toFixed(2)} dollars)`);
console.log(`   Result: ${result1} cents (${(result1/100).toFixed(2)} dollars)`);
console.log(`   Expected: ${10000 - 1000} cents (90.00 dollars)`);
console.log(`   Pass: ${result1 === 9000 ? "✓" : "✗"}\n`);

// Test 2: SAVE10 rounding to nearest cent
console.log("2. SAVE10 rounded to nearest cent:");
const subtotal2 = 15555;
const result2 = discountedSubtotal(subtotal2, "SAVE10");
const expectedRounded = subtotal2 - Math.round(subtotal2 * 0.1);
console.log(`   Input: ${subtotal2} cents (${(subtotal2/100).toFixed(2)} dollars)`);
console.log(`   10% of input: ${subtotal2 * 0.1} cents`);
console.log(`   Rounded: ${Math.round(subtotal2 * 0.1)} cents`);
console.log(`   Result: ${result2} cents`);
console.log(`   Expected: ${expectedRounded} cents`);
console.log(`   Pass: ${result2 === expectedRounded ? "✓" : "✗"}\n`);

// Test 3: FLAT5 takes 500 cents off
console.log("3. FLAT5 takes 500 cents off:");
const subtotal3 = 10000;
const result3 = discountedSubtotal(subtotal3, "FLAT5");
console.log(`   Input: ${subtotal3} cents (${(subtotal3/100).toFixed(2)} dollars)`);
console.log(`   Result: ${result3} cents (${(result3/100).toFixed(2)} dollars)`);
console.log(`   Expected: ${9500} cents (95.00 dollars)`);
console.log(`   Pass: ${result3 === 9500 ? "✓" : "✗"}\n`);

// Test 4: Result never below zero (SAVE10)
console.log("4. Result never below zero with SAVE10:");
const subtotal4 = 500;
const result4 = discountedSubtotal(subtotal4, "SAVE10");
console.log(`   Input: ${subtotal4} cents (${(subtotal4/100).toFixed(2)} dollars)`);
console.log(`   10% discount: ${Math.round(subtotal4 * 0.1)} cents`);
console.log(`   Result: ${result4} cents`);
console.log(`   Pass: ${result4 >= 0 ? "✓" : "✗"}\n`);

// Test 5: Result never below zero (FLAT5)
console.log("5. Result never below zero with FLAT5:");
const subtotal5 = 100;
const result5 = discountedSubtotal(subtotal5, "FLAT5");
console.log(`   Input: ${subtotal5} cents (${(subtotal5/100).toFixed(2)} dollars)`);
console.log(`   FLAT5 discount: 500 cents`);
console.log(`   Result: ${result5} cents`);
console.log(`   Expected: ${0} cents (can't go below zero)`);
console.log(`   Pass: ${result5 === 0 ? "✓" : "✗"}\n`);

// Test 6: Unknown code is rejected with error
console.log("6. Unknown code is rejected with error:");
try {
  discountedSubtotal(10000, "INVALID");
  console.log("   Pass: ✗ (no error thrown)");
} catch (err) {
  if (err instanceof UnknownDiscountCodeError) {
    console.log(`   Error thrown: ${err.message}`);
    console.log("   Pass: ✓");
  } else {
    console.log(`   Pass: ✗ (wrong error type: ${err.constructor.name})`);
  }
}
console.log();

// Test 7: No code provided returns subtotal unchanged
console.log("7. No code provided returns subtotal unchanged:");
const subtotal7 = 10000;
const result7 = discountedSubtotal(subtotal7);
console.log(`   Input: ${subtotal7} cents`);
console.log(`   Result: ${result7} cents`);
console.log(`   Pass: ${result7 === subtotal7 ? "✓" : "✗"}`);
EOF

